#include <stdio.h>

int main(void) {
    // int: whole numbers
    int apples = 12;
    int pears = 7;
    // double: numbers with decimals
    double price = 1.35;
    // char: a single character, between single quotes
    char grade = 'A';

    printf("Apples: %d\n", apples);
    printf("Pears: %d\n", pears);
    printf("Price per kilo: %f\n", price);
    printf("Quality grade: %c\n", grade);

    // A variable can change its value.
    apples = apples - 3;
    printf("Apples after selling 3: %d\n", apples);

    // A new variable can be calculated from others.
    int total = apples + pears;
    printf("Pieces of fruit: %d\n", total);

    // const: a value that cannot change.
    const double vat = 0.21;
    printf("Price with VAT: %f\n", price + price * vat);

    // sizeof tells how many bytes each type uses.
    printf("int: %zu bytes, double: %zu, char: %zu\n",
           sizeof(int), sizeof(double), sizeof(char));
    return 0;
}

#include <stdio.h>

int main(void) {
    int pizzas = 7, people = 3;

    // + - * / work as in maths...
    printf("Slices: %d\n", pizzas * 8);
    // ...but int / int drops the decimals.
    printf("Pizzas each: %d\n", pizzas / people);
    // % gives the remainder of the division.
    printf("Pizzas left over: %d\n", pizzas % people);

    // With a double in the division, the decimals stay.
    double share = (double)pizzas / people;
    printf("Exact share: %f\n", share);

    // Careful: the cast must come before the division.
    double too_late = (double)(pizzas / people);
    printf("Cast too late: %f\n", too_late);

    // Turning a double into an int cuts off the decimals.
    double bill = 47.85;
    int euros = (int)bill;
    int cents = (int)(bill * 100 + 0.5) % 100;
    printf("Bill: %d euros and %d cents\n", euros, cents);

    // Shortcuts that change a variable.
    int score = 10;
    score += 5;   // score = score + 5
    score *= 2;   // score = score * 2
    score++;      // add 1
    printf("Score: %d\n", score);
    return 0;
}

