#include <stdio.h>

int main(void) {
    char name[30];   // room for a word of up to 29 letters
    int age;
    double price;
    int adults, children;

    // %s reads one word. Text needs no &.
    printf("What is your name? ");
    scanf("%29s", name);
    printf("Nice to meet you, %s!\n", name);

    // For numbers, &age tells scanf where to store the value.
    printf("How old are you? ");
    scanf("%d", &age);
    printf("In 10 years you will be %d.\n", age + 10);

    // %lf reads a double (printf writes it with just %f).
    printf("Price of a cinema ticket? ");
    scanf("%lf", &price);
    printf("One ticket: %.2f euros.\n", price);

    // Two numbers on one line; scanf returns how many it read.
    printf("Adult and child tickets? ");
    int read = scanf("%d %d", &adults, &children);
    printf("(scanf read %d numbers)\n", read);

    // Children pay half price.
    double total = price * adults + price / 2 * children;
    printf("%d tickets cost %.2f euros.\n", adults + children, total);
    return 0;
}

#include <stdio.h>

int main(void) {
    // if runs its block only when the condition is true.
    int temperature = 31;
    if (temperature > 30)  // one statement: braces are optional
        printf("%d degrees: it is hot, drink water.\n", temperature);

    // else if and else choose one path among several.
    int score = 68;
    if (score >= 90) {
        printf("Score %d: excellent\n", score);
    } else if (score >= 60) {
        printf("Score %d: passed\n", score);
    } else {
        printf("Score %d: try again\n", score);
    }

    // switch compares one whole value with fixed cases.
    int day = 6;
    switch (day) {
        case 1: case 2: case 3: case 4: case 5:
            printf("Day %d: the shop opens at 9:00\n", day);
            break;  // without break, the next case would run too
        case 6: case 7:
            printf("Day %d: weekend, the shop opens at 10:00\n", day);
            break;
        default:
            printf("Day %d does not exist\n", day);
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int age = 15;
    int has_ticket = 1;  // in C, 0 is false and any other number is true
    double height = 1.42;

    // A comparison gives 1 (true) or 0 (false).
    printf("age == 15: %d\n", age == 15);
    printf("age != 18: %d\n", age != 18);
    printf("age >= 18: %d\n", age >= 18);

    // && (and): both sides must be true.
    if (has_ticket && height >= 1.40) {
        printf("You can ride the roller coaster.\n");
    }
    // || (or): at least one side must be true.
    if (age < 12 || age >= 65) {
        printf("Reduced price.\n");
    } else {
        printf("Full price.\n");
    }
    // ! (not) turns true into false and false into true.
    if (!has_ticket) printf("Buy a ticket first.\n");
    // A range: from 13 to 17, both included.
    int teen = age >= 13 && age <= 17;
    // condition ? a : b picks a when true, b when false.
    printf("Teenager? %s\n", teen ? "yes" : "no");

    // Remember: = assigns a value, == compares two values.
    int lives = 0;
    if (lives == 0) printf("Game over.\n");
    return 0;
}

#include <stdio.h>

int main(void) {
    // while repeats its block as long as the condition is true.
    double coffee = 90.0;
    int minute = 0;
    while (coffee > 60.0) {
        minute++;
        coffee *= 0.9;  // it loses 10% of its heat every minute
        printf("Minute %d: %.1f degrees\n", minute, coffee);
    }
    printf("Ready to drink after %d minutes.\n", minute);

    // A countdown.
    int seconds = 5;
    while (seconds > 0) {
        printf("%d... ", seconds);
        seconds--;
    }
    printf("Lift-off!\n");

    // do-while checks at the end, so the block runs at least once.
    // Counting digits: even 0 has one digit.
    int number = 2026, digits = 0;
    do {
        digits++;
        number /= 10;
    } while (number > 0);
    printf("2026 has %d digits.\n", digits);
    return 0;
}

#include <stdio.h>

int main(void) {
    // for (start; condition; step): everything about the counter in one line.
    for (int i = 1; i <= 5; i++) {
        printf("%d x 7 = %d\n", i, i * 7);
    }

    // Counting down in steps of 2.
    for (int n = 10; n > 0; n -= 2) printf("%d ", n);
    printf("\n");

    // Adding up: a bakery sells 20 loaves plus 3 more each day.
    int total = 0;
    for (int day = 1; day <= 7; day++) {
        total += 20 + 3 * day;
    }
    printf("Loaves sold this week: %d\n", total);

    // continue jumps to the next turn; break leaves the loop.
    for (int seat = 1; seat <= 20; seat++) {
        if (seat % 4 == 0) continue;  // every fourth seat is broken
        if (seat > 10) break;         // only the first row is open
        printf("seat %d ", seat);
    }
    printf("\n");

    // A loop inside a loop: rows and columns of a cinema.
    for (int row = 0; row < 3; row++) {
        for (int col = 1; col <= 5; col++) printf("%c%d ", 'A' + row, col);
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    // An array keeps several values of the same type, one after another.
    double temps[7] = {18.5, 21.0, 19.5, 24.0, 26.5, 22.0, 17.5};
    char days[7] = {'M', 'T', 'W', 'T', 'F', 'S', 'S'};
    int count = sizeof(temps) / sizeof(temps[0]);  // 7 elements

    // Positions start at 0: temps[0] is the first, temps[6] the last.
    printf("First: %.1f, last: %.1f\n", temps[0], temps[count - 1]);
    temps[2] = 20.0;  // change one element

    double sum = 0, max = temps[0];
    int hottest = 0;
    for (int i = 0; i < count; i++) {
        printf("%c %5.1f\n", days[i], temps[i]);
        sum += temps[i];
        if (temps[i] > max) {
            max = temps[i];
            hottest = i;
        }
    }
    printf("Average: %.2f\n", sum / count);
    printf("Hottest: day %d (%c), %.1f degrees\n", hottest + 1, days[hottest], max);

    // Elements without a value start at 0.
    int votes[4] = {3, 5};
    votes[3] += 2;
    for (int i = 0; i < 4; i++) printf("Option %d: %d votes\n", i + 1, votes[i]);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    // A string is a char array that ends with the character '\0'.
    char city[20] = "Madrid";
    printf("%s has %zu letters\n", city, strlen(city));
    printf("The array has room for %zu chars\n", sizeof(city));
    printf("First: %c, last: %c\n", city[0], city[strlen(city) - 1]);

    // = cannot copy an array: strcpy copies the text.
    char copy[20];
    strcpy(copy, city);
    copy[0] = 'm';
    printf("Original: %s, copy: %s\n", city, copy);

    // strcat adds text at the end (there must be room for it).
    char greeting[40] = "Hello from ";
    strcat(greeting, city);
    printf("%s\n", greeting);

    // strcmp gives 0 if equal, <0 or >0 for alphabetical order.
    char a[] = "pear", b[] = "apple";
    if (strcmp(a, b) == 0) printf("Same fruit\n");
    else if (strcmp(a, b) < 0) printf("%s comes before %s\n", a, b);
    else printf("%s comes before %s\n", b, a);

    // Walk the string until '\0', counting the letter 'o'.
    int found = 0;
    for (int i = 0; greeting[i] != '\0'; i++)
        if (greeting[i] == 'o') found++;
    printf("'%s' has the letter o %d times\n", greeting, found);
    return 0;
}

#include <stdio.h>

// A function groups code under a name. void: it gives nothing back.
void print_line(void) {
    printf("------------------------\n");
}

// This one receives a value: how many stars to draw.
void print_stars(int count) {
    for (int i = 0; i < count; i++) printf("*");
    printf("\n");
}

// This one gives a value back with return.
double celsius_to_fahrenheit(double celsius) {
    return celsius * 9 / 5 + 32;
}

int main(void) {
    print_line();
    printf("Hotel reviews\n");
    print_line();
    printf("Sea View   "); print_stars(5);
    printf("City Inn   "); print_stars(3);
    printf("Old Mill   "); print_stars(4);
    print_line();

    // The result can be used like any other value.
    printf("25 C is %.1f F\n", celsius_to_fahrenheit(25));
    double cold = celsius_to_fahrenheit(-5);
    printf("-5 C is %.1f F\n", cold);
    return 0;
}

#include <stdio.h>

// Prototypes announce the functions; their bodies come after main.
double apply_discount(double price, int percent);
int is_leap(int year);

int main(void) {
    // Arguments go in the same order as the parameters.
    printf("Headphones: %.2f\n", apply_discount(59.90, 20));
    printf("Keyboard:   %.2f\n", apply_discount(45.00, 15));

    // Parameters are copies: the function cannot change price here.
    double price = 10.0;
    apply_discount(price, 50);
    printf("price is still %.2f\n", price);
    price = apply_discount(price, 50);  // keep the returned value
    printf("now price is %.2f\n", price);

    int years[] = {1900, 2000, 2024, 2026};
    for (int i = 0; i < 4; i++)
        printf("%d: %s\n", years[i], is_leap(years[i]) ? "leap" : "normal");
    return 0;
}

double apply_discount(double price, int percent) {
    price = price * (100 - percent) / 100;  // changes only the copy
    return price;
}

int is_leap(int year) {
    if (year % 400 == 0) return 1;  // return ends the function at once
    if (year % 100 == 0) return 0;
    return year % 4 == 0;
}

#include <stdio.h>

int total_visits = 0;  // global: every function below can use it

void visit(const char page[]) {
    static int calls = 0;  // static: keeps its value between calls
    int local = 0;         // a normal local starts again on every call
    calls++;
    local++;
    total_visits++;
    printf("%-5s calls=%d local=%d\n", page, calls, local);
}

int next_ticket(void) {
    static int number = 100;  // set to 100 only the first time
    return ++number;          // add 1, then give the new value
}

int main(void) {
    visit("home");
    visit("shop");
    visit("cart");
    printf("Total visits: %d\n", total_visits);

    for (int i = 0; i < 3; i++) printf("Ticket %d\n", next_ticket());

    int lives = 3;
    {   // a block has its own scope: this lives hides the outer one
        int lives = 99;
        printf("inside the block: lives = %d\n", lives);
    }
    printf("outside the block: lives = %d\n", lives);
    return 0;
}

#include <stdio.h>

// With a pointer, a function can change the caller's variable.
void add_points(int *score, int points) {
    *score += points;
}

void swap(int *a, int *b) {
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

int main(void) {
    int score = 50;
    int *p = &score;  // & gives the address; p stores it

    // The address changes from run to run, so we only compare it.
    printf("p points to score: %s\n", p == &score ? "yes" : "no");
    printf("score = %d, *p = %d\n", score, *p);

    *p = 75;  // * follows the address and changes the value there
    printf("after *p = 75, score = %d\n", score);

    add_points(&score, 25);
    printf("after add_points, score = %d\n", score);

    int gold = 3, silver = 8;
    swap(&gold, &silver);
    printf("after swap: gold = %d, silver = %d\n", gold, silver);
    int *nowhere = NULL;  // NULL: points to nothing, check before use
    if (nowhere == NULL) printf("nowhere is NULL\n");
    return 0;
}

#include <stdio.h>

// An array parameter is really a pointer, so pass the length too.
double average(const double *values, int count) {
    double sum = 0;
    for (int i = 0; i < count; i++) sum += values[i];
    return sum / count;
}

// Through the pointer, the function changes the original array.
void add_bonus(int *marks, int count, int bonus) {
    for (int i = 0; i < count; i++) marks[i] += bonus;
}

int main(void) {
    int marks[] = {6, 8, 5, 9, 7};
    int n = sizeof(marks) / sizeof(marks[0]);

    int *p = marks;  // the array name is the address of marks[0]
    printf("*p = %d, *(p + 1) = %d, p[2] = %d\n", *p, *(p + 1), p[2]);

    // p + 1 moves one element forward, not one byte.
    for (int *q = marks; q < marks + n; q++) printf("%d ", *q);
    printf("<- marks\n");

    add_bonus(marks, n, 1);
    for (int i = 0; i < n; i++) printf("%d ", marks[i]);
    printf("<- after the bonus\n");

    double temps[] = {12.5, 15.0, 9.5};
    printf("Average temperature: %.2f\n", average(temps, 3));
    return 0;
}

#include <stdio.h>

// A struct groups related data under one name.
struct Product {
    char name[20];
    double price;
    int stock;
};

void show(struct Product p) {  // gets a copy: enough to read it
    printf("%-10s %6.2f  stock %2d\n", p.name, p.price, p.stock);
}

// A pointer lets the function change the struct; -> reaches its fields.
void sell(struct Product *p, int units) {
    if (units > p->stock) units = p->stock;
    p->stock -= units;
    printf("Sold %d x %s\n", units, p->name);
}

int main(void) {
    struct Product mug = {"Mug", 7.50, 12};
    struct Product lamp = {.name = "Lamp", .price = 24.90, .stock = 3};

    mug.price = 6.95;  // the dot reaches each field
    show(mug);
    show(lamp);

    sell(&mug, 5);
    sell(&lamp, 4);  // only 3 left
    show(mug);
    show(lamp);
    return 0;
}

#include <stdio.h>

// enum names a set of whole numbers: RED is 0, YELLOW 1, GREEN 2.
enum Light { RED, YELLOW, GREEN };

// typedef gives a type a short name; values can be chosen.
typedef enum { SMALL = 1, MEDIUM, LARGE } Size;  // MEDIUM is 2

typedef struct { char name[12]; Size size; double price; } Coffee;

enum Light next(enum Light light) {
    switch (light) {
        case RED:    return GREEN;
        case GREEN:  return YELLOW;
        default:     return RED;
    }
}

