    append(&todo, new_task(3, "Backup", NULL));  print("Start:", todo);
    remove_id(&todo, 2);                         print("Done 2:", todo);
    todo = new_task(4, "Server", todo);          print("Urgent:", todo);
    while (todo) { Task *next = todo->next; free(todo); todo = next; }  // free all
